<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {localFetch,readJson} from './http'
import {vRememberDisclosure} from './rememberDisclosure'
import ForwardPeRiverChart from './ForwardPeRiverChart.vue'
import ForwardPeSectors from './ForwardPeSectors.vue'
import type {ForwardRiver,ForwardRow,RiverWindow} from './forwardPeTypes'
const emit=defineEmits<{sector:[name:string]}>()
const sectors=ref<InstanceType<typeof ForwardPeSectors>|null>(null)
const props=defineProps<{initial?:ForwardRiver}>()
const data=ref<ForwardRiver|null>(props.initial||null),loading=ref(false),error=ref(''),years=ref<3|5>(5),role=ref('current_year'),seriesId=ref(''),search=ref('')
let alive=true
const valuation=computed(()=>data.value?.valuation)
const year=computed(()=>Number(valuation.value?.information_cutoff.slice(0,4)))
const period=computed(()=>valuation.value?.periods.find(p=>role.value==='NTM'?p.period_kind==='NTM':p.period_kind==='calendar_year'&&p.period===String(year.value+(role.value==='next_year'?1:0))))
const available=computed(()=>data.value?.series.filter(s=>s.key.role===role.value)||[])
const series=computed(()=>available.value.find(s=>s.id===seriesId.value)||available.value.at(-1))
const model=computed<RiverWindow>(()=>series.value?.windows[String(years.value)]||{years:years.value,status:'current_source_gap',points:[],observed_months:0,reference:{required_months:years.value*12,available_months:0,missing_months:Array.from({length:years.value*12},(_,i)=>{const d=new Date((valuation.value?.information_cutoff.slice(0,7)||'1970-01')+'-01T00:00:00Z');d.setUTCMonth(d.getUTCMonth()-years.value*12+i);return d.toISOString().slice(0,7)}),mean:null,sd:null,cuts:null},position:{z:null,percentile:null,label:null,color:null}})
const group=computed(()=>series.value?(series.value.key.method_version===valuation.value?.method_version&&series.value.key.policy_sha256===valuation.value.policy_sha256?period.value?.groups.find(g=>Object.entries(series.value!.key).filter(([k])=>['source_provider','provider','currency','eps_basis','share_basis','statistic','period_kind'].includes(k)).every(([k,v])=>g.series[k]===v)):undefined):period.value?.groups[0])
const baseRows=computed(()=>valuation.value?.periods.flatMap(p=>p.groups).find(g=>g.rows.length)?.rows||[])
const stockRows=computed(()=>{
 const rows:ForwardRow[]=group.value?.rows||baseRows.value.map(r=>({...r,estimate:null,individual_pe:null,qualified:false,issues:['missing_forecast']}))
 return rows.filter(r=>!search.value||`${r.symbol} ${r.name}`.includes(search.value.trim()))
})
const qualified=computed(()=>group.value?.qualified)
const preview=computed(()=>group.value?.mechanical_preview)
const exactPe=computed(()=>qualified.value?.exact_top50_pe??null)
const position=computed(()=>exactPe.value!==null?model.value?.position:undefined)
const reference=computed(()=>model.value?.reference)
const title=computed(()=>role.value==='NTM'?'未來12個月（NTM）':`${year.value+(role.value==='next_year'?1:0)} 年${role.value==='next_year'?'次年':'當年'}年度`)
const fmt=(n:number|null|undefined,d=2)=>n==null?'—':n.toLocaleString('zh-TW',{minimumFractionDigits:d,maximumFractionDigits:d})
const time=(s?:string)=>s?s.slice(0,19).replace('T',' '):'尚無保存'
const roleLabel=(r:string)=>r==='NTM'?'未來12個月（NTM）':`${year.value+(r==='next_year'?1:0)} 年${r==='next_year'?'次年':'當年'}年度`
const seriesLabel=(s:Record<string,string>)=>`${s.provider} · ${s.eps_basis==='basic'?'基本EPS':s.eps_basis==='diluted'?'稀釋EPS':'每股口徑未核對'}${s.method_version!==valuation.value?.method_version||s.policy_sha256!==valuation.value.policy_sha256?' · 舊口徑歷史':''}`
const savedPoints=computed(()=>model.value?.points.filter(p=>p.report_id).slice().reverse()||[])
async function load(){
 if(loading.value)return
 loading.value=true;error.value=''
 try{const r=await localFetch('/api/forward-pe/river'),j=await readJson(r);if(!r.ok)throw Error(j.error||'無法讀取已保存的估值');if(alive)data.value=j}catch(e){if(alive)error.value=(e as Error).message}finally{if(alive)loading.value=false}
}
watch(role,()=>seriesId.value='')
async function readSaved(){await Promise.all([load(),sectors.value?.reload()])}
onMounted(()=>{if(!props.initial)load()});onUnmounted(()=>{alive=false})
</script>
<template>
 <div class="forward-pe">
  <header class="page-heading"><div><small>FORWARD VALUATION · TOP 50</small><h1>預估本益比河流圖</h1><p>前50權值股的獲利預估與相對估值。先確認涵蓋範圍，再看歷史位置。</p></div><button :disabled="loading" @click="readSaved">{{loading?'讀取中…':'讀取最新保存'}}</button></header>
  <p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="loading&&!data" class="notice">正在讀取已保存的估值…</p>
  <p v-if="data&&!valuation" class="notice">尚無已保存的計算結果。完成資料匯入及估值保存後，這裡就會顯示；不會自動下載或補造數字。</p>
  <template v-if="valuation">
   <div class="controls"><label>預估期間<select v-model="role"><option v-for="r in ['current_year','next_year','NTM']" :key="r" :value="r">{{roleLabel(r)}}</option></select></label><label v-if="available.length>1">來源與口徑<select v-model="seriesId"><option v-for="s in available" :key="s.id" :value="s.id">{{seriesLabel(s.key)}}</option></select></label><small>股價 {{valuation.price_date}} · 權重名單 {{valuation.weight_date}}</small></div>
   <div v-if="exactPe===null" class="source-notice" role="status"><b>預估資料尚未齊全，暫不判定大盤貴便宜</b><span>{{title}}：公開EPS文件 {{period?.document_names||0}}／50檔，完整口徑核對 {{qualified?.names||0}}／50檔。<template v-if="role==='NTM'">不以年度EPS混成NTM。</template><template v-else>缺漏資料不補零、不外推；每股口徑仍須核對。</template></span></div>
   <div class="coverage"><div><small>股價與發行股數</small><b>{{valuation.quote_names}}<em>／50 檔</em></b></div><div><small>預估EPS文件</small><b>{{period?.document_names||0}}<em>／50 檔</em></b></div><div><small>完整口徑核對</small><b>{{qualified?.names||0}}<em>／50 檔</em></b></div><div><small>{{years}}年位階所需歷史</small><b>{{reference?.available_months||0}}<em>／{{years*12}} 個月</em></b></div></div>
   <div class="workspace">
    <aside class="stocks panel"><header><h2>權值股前50檔</h2><small>依 {{valuation.weight_date}} 官方排名</small></header><div class="stock-filter"><input v-model="search" type="search" placeholder="代碼或名稱" aria-label="搜尋權值股"/><small>EPS為文件值，資格另列；比例為原月底大盤權重。</small></div><div class="stock-scroll" tabindex="0" aria-label="前50檔預估EPS清單"><table><thead><tr><th>股票／比重</th><th>預估EPS</th><th>核對狀態</th></tr></thead><tbody><tr v-for="r in stockRows" :key="r.symbol"><th>{{r.name}}<small>{{r.symbol}} · {{fmt(r.weight_pct,2)}}%</small></th><td>{{fmt(r.estimate?.value)}}<a v-if="r.estimate" :href="r.estimate.source_url" target="_blank" rel="noopener noreferrer">來源 ↗</a></td><td><span :class="r.qualified?'verified':'missing'">{{r.qualified?'已核對':r.estimate?'待核對':'缺預估'}}</span></td></tr><tr v-if="!stockRows.length"><td colspan="3">沒有符合的股票。</td></tr></tbody></table></div></aside>
    <div class="center">
     <section class="panel river"><header><div><h2>{{title}}估值歷史</h2><small>前50完整成分籃子 · 共識中位數聚合</small></div><div class="years"><button v-for="n in ([3,5] as const)" :key="n" :aria-pressed="years===n" @click="years=n">{{n}}年</button></div></header>
      <ForwardPeRiverChart :window="model" :annual="role!=='NTM'" :preview-names="preview?.names||0"/>
      <div class="river-foot"><span>合格歷史 {{model?.observed_months||0}} 個保存月</span><span>缺少 {{reference?.missing_months.length??years*12}} 個參考月</span></div><p class="method-note">{{role==='NTM'?'NTM只用供應商明示的未來12個月。':'當年／次年年度會在年初換年，剩餘預估期間也會改變；不是NTM。'}} 彩色帶只描述過去估值位置。</p>
     </section>
     <details v-remember-disclosure="'forward-pe.preview'" class="panel preview"><summary>未核對試算與涵蓋範圍<span>{{preview?.names||0}} 檔</span></summary><p>只對有EPS的同一批股票計算市值／獲利；目前不是完整前50，更不是全大盤。以下數字尚未通過每股口徑核對。</p><div class="preview-values"><div><small>已覆蓋子集試算</small><b>{{fmt(preview?.matched_subset_pe)}} 倍</b></div><div><small>原月底籃子權重涵蓋</small><b>{{fmt(preview?.original_basket_weight_coverage_pct)}}%</b></div><div><small>行情日籃子市值涵蓋</small><b>{{fmt(preview?.revalued_basket_cap_coverage_pct)}}%</b></div></div><p>虧損與0EPS均保留；缺值不當0。試算倍數不能用來判斷台股昂貴或便宜。</p></details>
     <details v-remember-disclosure="'forward-pe.history-table'" class="panel history"><summary>保存月份與資料缺口</summary><p>一個月只取當月最後的有效資訊截點；完整資格未過就記為缺口，不退用同月較早數值。</p><div class="table-scroll"><table><thead><tr><th>保存月</th><th>完整前50估值</th><th>核對檔數</th><th>股價／資訊截點</th></tr></thead><tbody><tr v-for="p in savedPoints" :key="p.month"><td>{{p.month}}</td><td>{{p.pe===null?'未通過':fmt(p.pe)+' 倍'}}</td><td>{{p.qualified_names??0}}／50</td><td>{{p.price_date}}<small>{{time(p.information_cutoff)}}</small></td></tr><tr v-if="!savedPoints.length"><td colspan="4">此口徑沒有已保存月份。</td></tr></tbody></table></div><p v-if="reference?.missing_months.length">仍缺參考月份：{{reference.missing_months.join('、')}}</p></details>
    </div>
    <aside class="right-rail"><section class="valuation panel" :class="{unavailable:exactPe===null}"><header><h2>前50籃子評價</h2><small>與自身歷史比較，非全大盤</small></header><div class="position" :style="{color:position?.color||'#8a9680'}"><span>{{position?.label||'尚不能評價'}}</span><strong v-if="position?.z!=null">{{position.z>0?'+':''}}{{fmt(position.z)}}<small>標準差</small></strong><div v-if="position?.z!=null" class="position-scale" role="img" :aria-label="`歷史位階 ${fmt(position.z)} 個標準差`"><i v-for="c in ['#4e9179','#6c9db6','#d3bc6b','#cf9860','#b76562']" :key="c" :style="{background:c}"/><b :style="{left:Math.max(0,Math.min(100,(position.z+2)/4*100))+'%'}"/></div><div v-else class="no-position" aria-label="缺少位階，不顯示指針">—</div><p>{{position?.z!=null?'以先前保存月份計算的相對估值位置':exactPe===null?'預估口徑與涵蓋仍待補齊':model?.status==='flat_history'?'歷史波動為0，無法計算標準化位階':'連續歷史不足，尚不標示便宜或昂貴'}}</p></div><dl><div><dt>完整前50預估本益比</dt><dd>{{fmt(exactPe)}} 倍</dd></div><div><dt>{{years}}年歷史平均</dt><dd>{{fmt(reference?.mean)}} 倍</dd></div><div><dt>歷史估值百分位</dt><dd>{{fmt(position?.percentile,1)}}%</dd></div></dl><small class="read-note">百分位是過去估值的排序，不是未來上漲機率。位階按之前完整 {{years*12}} 個保存月計算，當月不進自己的基準。</small></section><ForwardPeSectors ref="sectors" compact @sector="emit('sector',$event)"/></aside>
   </div>
   <details v-remember-disclosure="'forward-pe.method'" class="panel method"><summary>計算方式、來源時間與限制</summary><p>個股收盤 ÷ 預估EPS；籃子為總市值 ÷ 總預估獲利。不是把個股本益比做算術平均。原始股數與未還原股價同日，每股調整須對齊。</p><p>五個色區依之前連續 {{years*12}} 個月的平均±0.5／±1個樣本標準差劃分。缺月不補值，完整50檔未過資格不畫入河流。3年與5年的尺度各自計算。</p><p v-for="note in data?.notes" :key="note">{{note}}</p><p>資訊截點 {{time(valuation.information_cutoff)}} · 計算保存 {{time(valuation.computed_at)}}。這是本機已保存資料，不表示已完成Google Drive讀回校驗。</p></details>
   <p v-for="warning in data?.warnings" :key="warning.id" class="notice error">{{warning.message}}</p>
  </template>
  <ForwardPeSectors v-if="data&&!valuation" ref="sectors" @sector="emit('sector',$event)"/>
 </div>
</template>
<style scoped>
.forward-pe{min-width:0;color:#354c3d}.page-heading{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:24px}.page-heading small{font-size:10px;letter-spacing:.15em;color:#8c9b81}.page-heading h1{font-size:30px;margin:9px 0}.page-heading p{font-size:13px;color:#7b8b72;margin:0;line-height:1.8}.page-heading button{white-space:nowrap}.forward-pe button,.forward-pe select,.stock-filter input{border:1px solid #dce5d6;background:#fff;border-radius:7px;color:#56714f;font:inherit;font-size:12px;padding:9px 12px}.forward-pe button{cursor:pointer}.forward-pe button:disabled{opacity:.6;cursor:wait}.controls{display:flex;align-items:center;gap:16px;flex-wrap:wrap;font-size:12px;margin-bottom:18px}.controls label{display:flex;align-items:center;gap:9px}.controls small{margin-left:auto;color:#88967e;font-size:11px}.source-notice{display:flex;flex-direction:column;gap:7px;padding:17px 20px;border:1px solid #e9ddbc;background:#fcf8eb;border-radius:9px;color:#90733e;font-size:12px;line-height:1.8;margin-bottom:18px}.source-notice b{font-size:14px;font-weight:500}.coverage{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));background:#fff;border:1px solid #e1e7dc;border-radius:12px;margin-bottom:22px}.coverage>div{padding:18px 22px;border-right:1px solid #edf0e8}.coverage small{font-size:11px;color:#8b9881;display:block}.coverage b{font-size:25px;font-weight:500;display:block;margin-top:9px;color:#4f6d51}.coverage em{font-size:12px;color:#93a087;font-style:normal}.workspace{display:grid;grid-template-columns:250px minmax(0,1fr) 235px;gap:18px;align-items:start}.workspace>*{min-width:0}.panel{border:1px solid #e0e7da;border-radius:12px;background:#fff;overflow:hidden}.panel header{padding:20px;border-bottom:1px solid #edf0e8;display:flex;justify-content:space-between;gap:12px;align-items:center}.panel h2{font-size:16px;margin:0 0 6px;font-weight:600}.panel header small{font-size:10px;color:#8d9a82}.stocks header{display:block}.stock-filter{pad