der:1}.right-rail{grid-column:1;order:2}.coverage{grid-template-columns:repeat(2,minmax(0,1fr))}.coverage>div{border-bottom:1px solid #edf0e8}.stock-scroll{max-height:430px}.page-heading{align-items:flex-start}.controls small{width:100%;margin:0}}@media(max-width:600px){.page-heading{flex-direction:column}.page-heading h1{font-size:25px}.controls{gap:12px}.controls label{flex-wrap:wrap}.coverage>div{padding:16px}.coverage b{font-size:22px}.preview-values{grid-template-columns:1fr}.valuation dl{display:block}.panel header{flex-wrap:wrap}}
